mapper.update:
update talk_session
talk_type = #{talkType}, talk_time = #{talkTime}, talk_location = #{talkLocation}, talk_person = #{talkPerson}, talk_content = #{talkContent}, update_by = #{updateBy}, update_time = #{updateTime}, revision = revision + 1,
where session_id = #{sessionId}

mapper.select:
select DATE_FORMAT(talk_time, '%Y-%m') as month, count(*) as cnt
from talk_session group by DATE_FORMAT(talk_time, '%Y-%m')
order by month asc limit 12

select recent.month, recent.cnt
from (
    select DATE_FORMAT(ts.talk_time, '%Y-%m') as month, count(*) as cnt
    from talk_session ts
    
         and ts.college_dept_id = #{collegeDeptId}
    
    group by DATE_FORMAT(ts.talk_time, '%Y-%m')
    order by month desc
    limit 12
) recent
order by recent.month asc

select ts.talk_type as type, count(*) as cnt from talk_session ts
and ts.college_dept_id = #{collegeDeptId}
group by ts.talk_type
